===== FILE: index.html =====
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>悦容美发美容</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 0;
        }
        .header {
            background-color: #f0f0f0;
            padding: 20px;
            text-align: center;
        }
        .header img {
            width: 100px;
            height: 100px;
            border-radius: 50%;
        }
        .nav {
            background-color: #333;
            color: #fff;
            padding: 10px;
            text-align: center;
        }
        .nav a {
            color: #fff;
            text-decoration: none;
            margin: 0 20px;
        }
        .nav a:hover {
            color: #ccc;
        }
        .main {
            display: flex;
            flex-direction: column;
            align-items: center;
            padding: 20px;
        }
        .main h1 {
            font-size: 24px;
            margin-bottom: 10px;
        }
        .main p {
            margin-bottom: 20px;
        }
        .button {
            background-color: #333;
            color: #fff;
            border: none;
            padding: 10px 20px;
            font-size: 16px;
            cursor: pointer;
        }
        .button:hover {
            background-color: #444;
        }
        .footer {
            background-color: #f0f0f0;
            padding: 10px;
            text-align: center;
            clear: both;
        }
    </style>
</head>
<body>
    <div class="header">
        <img src="logo.jpg" alt="悦容美发美容">
        <h1>悦容美发美容</h1>
    </div>
    <div class="nav">
        <a href="index.html">首页</a>
        <a href="services.html">服务</a>
        <a href="team.html">团队</a>
        <a href="appointment.html">预约</a>
    </div>
    <div class="main">
        <h1>欢迎来到悦容美发美容</h1>
        <p>我们是一家专业的美发美容沙龙，位于广州市中心。我们的团队由经验丰富的发型师和美容师组成，致力于为您提供最好的服务。</p>
        <button class="button" onclick="location.href='appointment.html'">立即预约</button>
    </div>
    <div class="footer">
        <p>&copy; 2023 悦容美发美容</p>
    </div>
</body>
</html>

